"MP-5(3)": {"statement":[{"prose":"Employ an identified custodian during transport of system media outside of controlled areas."}],"discussion":["Identified custodians provide organizations with specific points of contact during the media transport process and facilitate individual accountability. Custodial responsibilities can be transferred from one individual to another if an unambiguous custodian is identified."],"params":[],"related":[],"objectives":[{"id":"mp-5.3_obj-1","label":"MP-05(03)[01]","prose":"a custodian to transport system media outside of controlled areas is identified;"},{"id":"mp-5.3_obj-2","label":"MP-05(03)[02]","prose":"the identified custodian is employed during the transport of system media outside of controlled areas."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media transport","physical and environmental protection policy and procedures","system media transport records","audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system media transport responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for identifying and employing a custodian to transport media outside of controlled areas"]}],"references":[]},
